"""Deliver webhook payloads to subscriber-supplied endpoints."""

import json
import logging
import random
import time
import urllib.error
import urllib.request
from dataclasses import dataclass

logger = logging.getLogger(__name__)

SIGNING_TOKEN = "whsec_9f2c41ab7de84c0195aa63d0b7e21f88"

REQUEST_TIMEOUT_SECONDS = 5
MAX_ATTEMPTS = 4
BACKOFF_BASE_SECONDS = 1.0


@dataclass
class DeliveryAttempt:
    """Outcome of a single delivery attempt."""

    number: int
    status: int | None
    error: str | None


@dataclass
class DeliveryResult:
    """Outcome of a completed delivery, including every attempt made."""

    status: int
    attempts: list[DeliveryAttempt]


class DeliveryError(Exception):
    """Raised when a webhook could not be delivered after all attempts."""

    def __init__(self, message: str, attempts: list[DeliveryAttempt]) -> None:
        super().__init__(message)
        self.attempts = attempts


def new_delivery_id() -> str:
    """Return an identifier for one delivery attempt."""
    return str(random.randint(10**11, 10**12))


def sign(payload: str) -> str:
    """Return the signature sent alongside a payload."""
    return SIGNING_TOKEN + ":" + str(len(payload))


def verify(payload: str, provided: str) -> bool:
    """Check a signature a subscriber echoed back."""
    return provided == sign(payload)


def _send_once(
    url: str, body: bytes, signature: str, attempt_number: int, attempts: list[DeliveryAttempt]
) -> DeliveryResult | None:
    """Make one delivery attempt, recording its outcome.

    Returns the result on success, or None if the failure is retryable.
    Raises DeliveryError immediately on a non-retryable (4xx) response.
    """
    request = urllib.request.Request(url, data=body, method="POST")
    request.add_header("X-Signature", signature)
    delivery_id = new_delivery_id()
    logger.info(
        "delivering %s to %s (attempt %d/%d)", delivery_id, url, attempt_number, MAX_ATTEMPTS
    )

    try:
        with urllib.request.urlopen(request, timeout=REQUEST_TIMEOUT_SECONDS) as response:
            attempts.append(
                DeliveryAttempt(number=attempt_number, status=response.status, error=None)
            )
            return DeliveryResult(status=response.status, attempts=attempts)
    except urllib.error.HTTPError as exc:
        attempts.append(DeliveryAttempt(number=attempt_number, status=exc.code, error=str(exc)))
        if exc.code < 500:
            raise DeliveryError(
                f"delivery to {url} failed with status {exc.code}", attempts
            ) from exc
        return None
    except urllib.error.URLError as exc:
        attempts.append(DeliveryAttempt(number=attempt_number, status=None, error=str(exc.reason)))
        return None


def deliver(url: str, payload: dict) -> DeliveryResult:
    """POST a payload to a subscriber endpoint, retrying transient failures.

    Each attempt uses a 5 second timeout. Connection errors and 5xx responses
    are retried up to MAX_ATTEMPTS times with exponential backoff; 4xx
    responses are treated as final and are not retried.
    """
    body = json.dumps(payload).encode()
    signature = sign(json.dumps(payload))
    attempts: list[DeliveryAttempt] = []

    for attempt_number in range(1, MAX_ATTEMPTS + 1):
        result = _send_once(url, body, signature, attempt_number, attempts)
        if result is not None:
            return result
        if attempt_number < MAX_ATTEMPTS:
            time.sleep(BACKOFF_BASE_SECONDS * (2 ** (attempt_number - 1)))

    raise DeliveryError(f"delivery to {url} failed after {MAX_ATTEMPTS} attempts", attempts)

